        ok: true,
        id: stage.id,
        plusText: plus.textContent.trim(),
        minusText: minus.textContent.trim(),
        plusAfterMinus: pr.left > mr.left,
        rightGap: sr.right - pr.right,
        inBox: pr.top >= sr.top - 1 && pr.bottom <= sr.bottom + 1
      };
    });
    return {
      hasBar: !!bar,
      noPageWide: !pageWide,
      stageCount: stages.length,
      boxes: boxes
    };
  })()`);
